module sorted_pair (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire ins,
    input wire rem,
    input wire [7:0] val,
    output reg [1:0] count
);
    reg [7:0] e0, e1, max_shadow;
    initial begin count = 2'd0; e0 = 8'd0; e1 = 8'd0; max_shadow = 8'd0; end

    wire do_ins = i_ce && ins && !rem && (count != 2'd2);
    wire do_rem = i_ce && rem && !ins && (count != 2'd0);

    always @(posedge clk) begin
        if (rst) begin
            count <= 2'd0; e0 <= 8'd0; e1 <= 8'd0; max_shadow <= 8'd0;
        end else if (do_ins) begin
            count <= count + 2'd1;
            if (count == 2'd0) begin
                e0 <= val;  max_shadow <= val;
            end else if (val >= e0) begin
                e1 <= val;  max_shadow <= val;
            end else begin
                e0 <= val;  e1 <= e0;  max_shadow <= e0;
            end
        end else if (do_rem) begin
            count <= count - 2'd1;
            if (count == 2'd2) e0 <= e1;
        end
    end

    always @(posedge clk)
        if (count == 2'd1)
            assert (max_shadow == e0);
endmodule

module gcd_ctrl (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire       ack,
    input  wire [3:0] x,
    input  wire [3:0] y,
    output reg  [3:0] a,
    output reg  [3:0] b,
    output reg        idle,
    output reg        calc,
    output reg        done
);
    initial begin a = 4'd0; b = 4'd0; idle = 1'b1; calc = 1'b0; done = 1'b0; end

    wire finish = (b == 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            idle <= (idle && !start) || (done && ack);
            calc <= (idle && start)  || (calc && !finish);
            done <= (calc && finish) || (done && !ack);

            if (idle && start) begin
                a <= x;
                b <= y;
            end else if (calc && !finish) begin
                if (a >= b) begin
                    a <= a - b;
                end else begin
                    a <= b;
                    b <= a;
                end
            end
        end
    end

    always @(posedge clk)
        if (done)
            assert (!calc);
endmodule

module char_occurrence_scan (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire ch_match,
    output reg [3:0] nchars,
    output reg [3:0] nmatch,
    output wire done
);
    initial nchars = 4'd0;
    initial nmatch = 4'd0;

    // scan a fixed 8-character string, counting occurrences of the target char
    assign done = (nchars == 4'd8);

    always @(posedge clk) begin
        if (rst) begin
            nchars <= 4'd0;
            nmatch <= 4'd0;
        end else if (ce && !done) begin
            nchars <= nchars + 4'd1;
            if (ch_match)
                nmatch <= nmatch + 4'd1;
        end
    end

    // P: if every character matched, the whole string must have been consumed
    always @(posedge clk)
        if (nmatch == 4'd8)
            assert (nchars == 4'd8);
endmodule

module ringq (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] dout,
    output wire full,
    output wire empty
);
    reg [1:0] wptr = 2'd0;
    reg [1:0] rptr = 2'd0;
    reg [2:0] count = 3'd0;
    reg [7:0] mem [0:3];

    assign full  = (count == 3'd4);
    assign empty = (count == 3'd0);

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
        end else begin
            if (do_push) begin
                mem[wptr] <= din;
                wptr <= wptr + 2'd1;
            end
            if (do_pop)
                rptr <= rptr + 2'd1;
            if (do_push && !do_pop)
                count <= count + 3'd1;
            else if (do_pop && !do_push)
                count <= count - 3'd1;
        end
    end

    assign dout = mem[rptr];

    always @(posedge clk)
        if (count == 3'd0) assert (wptr == rptr);
endmodule

module stack_xor (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [3:0] data,
    output reg [2:0] sp,
    output reg [3:0] xor_acc
);
    reg [3:0] m0, m1, m2, m3;
    initial begin sp = 0; xor_acc = 0; m0 = 0; m1 = 0; m2 = 0; m3 = 0; end

    wire do_push = push && !pop && (sp != 3'd4);
    wire do_pop  = pop  && !push && (sp != 3'd0);
    wire [3:0] top = (sp == 3'd1) ? m0 : (sp == 3'd2) ? m1 : (sp == 3'd3) ? m2 : m3;

    always @(posedge clk) begin
        if (rst) begin
            sp <= 3'd0;
            xor_acc <= 4'd0;
        end else if (do_push) begin
            case (sp)
                3'd0:    m0 <= data;
                3'd1:    m1 <= data;
                3'd2:    m2 <= data;
                default: m3 <= data;
            endcase
            sp <= sp + 3'd1;
            xor_acc <= xor_acc ^ data;
        end else if (do_pop) begin
            sp <= sp - 3'd1;
            xor_acc <= xor_acc ^ top;
        end
    end

    always @(posedge clk)
        if (sp == 3'd0)
            assert (xor_acc == 4'd0);
endmodule

module ringq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire push,
    input wire pop
);
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg       empty_r, full_r;
    initial begin wptr = 2'd0; rptr = 2'd0; count = 3'd0; empty_r = 1'b1; full_r = 1'b0; end

    wire do_push = i_ce && push && !full_r;
    wire do_pop  = i_ce && pop  && !empty_r;
    wire [1:0] nw = wptr + do_push;
    wire [1:0] nr = rptr + do_pop;

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 2'd0; rptr <= 2'd0; count <= 3'd0;
            empty_r <= 1'b1; full_r <= 1'b0;
        end else begin
            wptr <= nw;
            rptr <= nr;
            empty_r <= (nw == nr) && (do_pop  || (empty_r && !do_push));
            full_r  <= (nw == nr) && (do_push || (full_r  && !do_pop));
            count <= count + do_push - do_pop;
        end
    end

    always @(posedge clk)
        if (empty_r)
            assert (!full_r);
endmodule

module char_tally (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [7:0] i_char,
    input wire [7:0] i_target,
    output wire o_all_hits,
    output wire o_all_misses
);
    reg [3:0] total, hits, misses;
    initial total  = 4'd0;
    initial hits   = 4'd0;
    initial misses = 4'd0;

    wire match = (i_char == i_target);

    always @(posedge clk)
        if (rst) begin
            total  <= 4'd0;
            hits   <= 4'd0;
            misses <= 4'd0;
        end else if (i_ce && (total != 4'hf)) begin
            total <= total + 4'd1;
            if (match) hits   <= hits   + 4'd1;
            else       misses <= misses + 4'd1;
        end

    assign o_all_hits   = (total != 4'd0) && (hits   == total);
    assign o_all_misses = (total != 4'd0) && (misses == total);

    always @(*)
        if (o_all_hits) assert (!o_all_misses);
endmodule

module stack_ptr_guard (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] dout,
    output reg [2:0] sp,
    output reg empty,
    output reg full
);
    reg [7:0] mem [0:3];

    initial sp    = 3'd0;
    initial empty = 1'b1;
    initial full  = 1'b0;

    assign dout = empty ? 8'h00 : mem[sp - 3'd1];

    always @(posedge clk) begin
        if (rst) begin
            sp    <= 3'd0;
            empty <= 1'b1;
            full  <= 1'b0;
        end else if (push && !pop && !full) begin
            mem[sp] <= din;
            sp      <= sp + 3'd1;
            empty   <= 1'b0;
            full    <= (sp == 3'd3);
        end else if (pop && !push && !empty) begin
            sp    <= sp - 3'd1;
            full  <= 1'b0;
            empty <= (sp == 3'd1);
        end
    end

    always @(posedge clk)
        if (!full) assert (sp <= 3'd4);
endmodule

module qring (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_push,
    input  wire       i_pop,
    output wire       o_full,
    output wire       o_empty
);
    reg [1:0] wptr;
    reg [1:0] rptr;
    reg [2:0] count;

    initial wptr  = 2'd0;
    initial rptr  = 2'd0;
    initial count = 3'd0;

    assign o_full  = (count == 3'd4);
    assign o_empty = (count == 3'd0);

    wire do_push = i_push && !o_full;
    wire do_pop  = i_pop  && !o_empty;

    always @(posedge clk)
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
        end else begin
            if (do_push) wptr <= wptr + 2'd1;
            if (do_pop)  rptr <= rptr + 2'd1;
            if (do_push && !do_pop) count <= count + 3'd1;
            else if (do_pop && !do_push) count <= count - 3'd1;
        end

    always @(*)
        if (count == 3'd0)
            assert (wptr == rptr);
endmodule

module strcount_pipe (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire flush,
    input wire [7:0] ch,
    output wire [5:0] o_cnt
);
    parameter [7:0] TARGET = 8'h61;

    reg [5:0] total = 6'd0;   // characters accepted
    reg [5:0] cnt   = 6'd0;   // committed occurrences of TARGET
    reg       st_valid = 1'b0; // staged character present
    reg       st_match = 1'b0; // staged character equals TARGET

    wire full   = (total == 6'd63);
    wire accept = ce && !full;

    always @(posedge clk)
        if (rst) begin
            total    <= 6'd0;
            cnt      <= 6'd0;
            st_valid <= 1'b0;
            st_match <= 1'b0;
        end else if (accept) begin
            total    <= total + 6'd1;
            st_valid <= 1'b1;
            st_match <= (ch == TARGET);
            if (st_valid && st_match)
                cnt <= cnt + 6'd1;
        end else if (flush && st_valid) begin
            st_valid <= 1'b0;
            if (st_match)
                cnt <= cnt + 6'd1;
        end

    assign o_cnt = cnt;

    always @(*)
        if (!st_valid)
            assert (cnt <= total);
endmodule

module stack_occupancy (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    output reg [2:0] sp,
    output reg [2:0] items,
    output reg top_valid
);
    initial sp = 3'd0;
    initial items = 3'd0;
    initial top_valid = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            sp        <= 3'd0;
            items     <= 3'd0;
            top_valid <= 1'b0;
        end else if (push && sp != 3'd4) begin
            sp        <= sp + 3'd1;
            items     <= items + 3'd1;
            top_valid <= 1'b1;
        end else if (pop && sp != 3'd0) begin
            sp        <= sp - 3'd1;
            items     <= items - 3'd1;
            top_valid <= (sp != 3'd1);
        end
    end

    // P: an empty stack (per the occupancy counter) must not advertise a valid top
    always @(posedge clk)
        if (items == 3'd0)
            assert (top_valid == 1'b0);
endmodule

module uart_tx (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire start,
    input wire [7:0] data,
    output reg tx
);
    localparam IDLE = 2'd0, ST = 2'd1, DAT = 2'd2, STP = 2'd3;
    reg [1:0] phase;
    reg [2:0] bit_cnt;
    reg [7:0] sh;
    initial begin phase = IDLE; bit_cnt = 3'd0; sh = 8'h00; tx = 1'b1; end

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE; bit_cnt <= 3'd0; sh <= 8'h00; tx <= 1'b1;
        end else if (ce) begin
            case (phase)
                IDLE: if (start) begin
                          phase <= ST; sh <= data; tx <= 1'b0; bit_cnt <= 3'd0;
                      end
                ST:   begin
                          phase <= DAT; tx <= sh[0]; sh <= {1'b0, sh[7:1]};
                          bit_cnt <= 3'd0;
                      end
                DAT:  if (bit_cnt == 3'd7) begin
                          phase <= STP; tx <= 1'b1; bit_cnt <= 3'd0;
                      end else begin
                          bit_cnt <= bit_cnt + 3'd1; tx <= sh[0];
                          sh <= {1'b0, sh[7:1]};
                      end
                STP:  begin phase <= IDLE; tx <= 1'b1; end
            endcase
        end
    end

    always @(posedge clk)
        if (phase == IDLE)
            assert (bit_cnt == 3'd0);
endmodule

module stack_occupancy (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] data,
    output wire [7:0] o_top,
    output wire empty,
    output wire full
);
    parameter DEPTH = 8;
    reg [3:0] sp   = 4'd0;   // occupancy / stack pointer
    reg [3:0] free = 4'd8;   // mirrored free-slot count
    reg [7:0] mem [0:7];
    integer i;
    initial for (i = 0; i < 8; i = i + 1) mem[i] = 8'h00;

    assign empty = (sp == 4'd0);
    assign full  = (sp == DEPTH[3:0]);

    wire do_push = push && !pop && !full;
    wire do_pop  = pop  && !push && !empty;

    always @(posedge clk)
        if (rst) begin
            sp   <= 4'd0;
            free <= 4'd8;
        end else if (do_push) begin
            sp   <= sp + 4'd1;
            free <= free - 4'd1;
        end else if (do_pop) begin
            sp   <= sp - 4'd1;
            free <= free + 4'd1;
        end

    always @(posedge clk)
        if (!rst && do_push) mem[sp[2:0]] <= data;

    assign o_top = empty ? 8'h00 : mem[sp[2:0] - 3'd1];

    always @(*)
        if (!empty) assert (free <= 4'd7);
endmodule

module intersection_phase_pair (
    input wire clk,
    input wire rst,
    input wire ce,
    output reg [2:0] a_ph,
    output reg [2:0] b_ph,
    output reg [2:0] timer
);
    // phase 0 = GREEN, 1 = YELLOW, 2 = ALL_RED, 3..5 = red while the other road runs
    localparam [2:0] LAST = 3'd5;
    localparam [2:0] DUR  = 3'd4;

    initial a_ph  = 3'd0;
    initial b_ph  = 3'd3;
    initial timer = DUR;

    always @(posedge clk) begin
        if (rst) begin
            a_ph  <= 3'd0;
            b_ph  <= 3'd3;
            timer <= DUR;
        end else if (ce) begin
            if (timer == 3'd0) begin
                a_ph  <= (a_ph == LAST) ? 3'd0 : a_ph + 3'd1;
                b_ph  <= (b_ph == LAST) ? 3'd0 : b_ph + 3'd1;
                timer <= DUR;
            end else begin
                timer <= timer - 3'd1;
            end
        end
    end

    // P: when road A holds its green phase, road B must not also be in its green phase
    always @(posedge clk)
        if (a_ph == 3'd0) assert (b_ph != 3'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module wdog_kick (
    input wire clk,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output wire o_reset
);
    reg [3:0] cnt;
    reg zf, armed, fault;
    initial cnt   = 4'd0;
    initial zf    = 1'b1;
    initial armed = 1'b0;
    initial fault = 1'b0;

    always @(posedge clk) if (i_ce) begin
        if (ack) begin
            fault <= 1'b0;
            armed <= 1'b0;
            cnt   <= 4'd0;
            zf    <= 1'b1;
        end else if (kick && !fault) begin
            armed <= 1'b1;
            cnt   <= 4'd8;
            zf    <= 1'b0;
        end else if (armed) begin
            if (zf) fault <= 1'b1;            // expiry seen through the flag
            if (cnt == 4'd0) armed <= 1'b0;   // disarm seen through the count
            else begin
                cnt <= cnt - 4'd1;
                zf  <= (cnt == 4'd1);
            end
        end
    end

    assign o_reset = fault;

    always @(*)
        if (fault) assert (!armed);
endmodule

module thermo_window (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire warmer,
    output reg heat
);
    localparam [3:0] T_LOW  = 4'd4;
    localparam [3:0] T_HIGH = 4'd12;

    reg [3:0] temp;
    reg [1:0] win, heat_cycles, cool_cycles;

    initial begin
        temp = 4'd8; heat = 1'b0;
        win = 2'd0; heat_cycles = 2'd0; cool_cycles = 2'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            temp <= 4'd8; heat <= 1'b0;
            win <= 2'd0; heat_cycles <= 2'd0; cool_cycles <= 2'd0;
        end else if (ce) begin
            win <= win + 2'd1;
            if (heat) heat_cycles <= heat_cycles + 2'd1;
            else      cool_cycles <= cool_cycles + 2'd1;
            temp <= warmer ? ((temp == 4'd15) ? temp : temp + 4'd1)
                           : ((temp == 4'd0)  ? temp : temp - 4'd1);
            if      (temp <= T_LOW)  heat <= 1'b1;
            else if (temp >= T_HIGH) heat <= 1'b0;
        end
    end

    always @(posedge clk)
        if (cool_cycles == 2'd0)
            assert (heat_cycles == win);
endmodule

module strscan (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] ch,
    input wire [7:0] target,
    output wire done,
    output wire [3:0] hits
);
    parameter LEN = 8;

    reg [3:0] remaining;
    reg [3:0] consumed;
    reg [3:0] match_count;

    initial remaining   = LEN;
    initial consumed    = 0;
    initial match_count = 0;

    always @(posedge clk)
        if (rst) begin
            remaining   <= LEN;
            consumed    <= 0;
            match_count <= 0;
        end else if (ce && (remaining != 4'd0)) begin
            remaining <= remaining - 4'd1;
            consumed  <= consumed  + 4'd1;
            if (ch == target)
                match_count <= match_count + 4'd1;
        end

    assign done = (remaining == 4'd0);
    assign hits = match_count;

    // P: once the whole string has been scanned, every character was consumed
    always @(*)
        if (remaining == 4'd0)
            assert (consumed == LEN);
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] rd_data,
    output reg  [3:0] wr_addr,
    output reg  [3:0] remaining,
    output reg  [7:0] wr_data,
    output wire       done
);
    localparam [3:0] TOTAL = 4'd8;

    initial wr_addr   = 4'd0;
    initial remaining = TOTAL;
    initial wr_data   = 8'h00;

    assign done = (remaining == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            wr_addr   <= 4'd0;
            remaining <= TOTAL;
            wr_data   <= 8'h00;
        end else if (ce && remaining != 4'd0) begin
            wr_addr   <= wr_addr + 4'd1;
            remaining <= remaining - 4'd1;
            wr_data   <= rd_data;
        end
    end

    // P: while the block copy is still in flight, the write pointer must stay
    // inside the destination block (0..7).
    always @(posedge clk)
        if (!done)
            assert (wr_addr <= 4'd7);
endmodule

module ring_occ (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    output reg  [2:0] count,
    output reg  [3:0] occ
);
    reg [1:0] wptr, rptr;
    initial begin wptr = 2'd0; rptr = 2'd0; count = 3'd0; occ = 4'b0000; end

    wire do_push = push && (count != 3'd4);
    wire do_pop  = pop  && (count != 3'd0);

    wire [3:0] set_bit = do_push ? (4'b0001 << wptr) : 4'b0000;
    wire [3:0] clr_bit = do_pop  ? (4'b0001 << rptr) : 4'b0000;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
            occ   <= 4'b0000;
        end else begin
            if (do_push) wptr <= wptr + 2'd1;
            if (do_pop)  rptr <= rptr + 2'd1;
            occ <= (occ | set_bit) & ~clr_bit;
            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase
        end
    end

    always @(posedge clk)
        if (count == 3'd1)
            assert (occ == 4'b0001 || occ == 4'b0010 ||
                    occ == 4'b0100 || occ == 4'b1000);
endmodule

module rot_shadow (
    input wire clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_load,
    input wire [15:0] i_data,
    output wire [15:0] o_word,
    output wire [15:0] o_shadow
);
    reg [15:0] word   = 16'h0000;
    reg [15:0] shadow = 16'h0000;
    reg [3:0]  amt    = 4'd0;

    always @(posedge clk)
        if (i_rst) begin
            word   <= 16'h0000;
            shadow <= 16'h0000;
            amt    <= 4'd0;
        end else if (i_ce) begin
            if (i_load) begin
                word   <= i_data;
                shadow <= i_data;
                amt    <= 4'd0;
            end else begin
                shadow <= { shadow[14:0], shadow[15] };
                amt    <= amt + 4'd1;
            end
        end

    assign o_word   = word;
    assign o_shadow = shadow;

    always @(*)
        if (amt == 4'd0)
            assert (shadow == word);
endmodule

module lfsr_capture (
    input wire clk,
    input wire rst,
    input wire ce,
    output reg [7:0] out,
    output reg valid
);
    reg [7:0] s = 8'h01;
    wire fb = s[7] ^ s[5] ^ s[4] ^ s[3];

    initial out   = 8'h00;
    initial valid = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            s     <= 8'h01;
            out   <= 8'h00;
            valid <= 1'b0;
        end else if (ce) begin
            s     <= {s[6:0], fb};
            out   <= s;
            valid <= 1'b1;
        end
    end

    always @(posedge clk)
        if (valid) assert (out != 8'h00);
endmodule

module elevator_ctrl (
    input wire clk,
    input wire rst,
    input wire step,
    output reg [1:0] floor,
    output reg dir
);
    // one-hot shadow of the cab position, shifted in lockstep with floor
    reg [3:0] pos;
    initial begin floor = 2'd0; dir = 1'b1; pos = 4'b0001; end

    wire go_up   = step &&  dir && (floor != 2'd3);
    wire go_down = step && !dir && (floor != 2'd0);

    always @(posedge clk) begin
        if (rst) begin
            floor <= 2'd0;
            dir   <= 1'b1;
            pos   <= 4'b0001;
        end else begin
            if (go_up) begin
                floor <= floor + 2'd1;
                pos   <= pos << 1;
            end else if (go_down) begin
                floor <= floor - 2'd1;
                pos   <= pos >> 1;
            end
            if (step) begin
                if (dir && (floor == 2'd3))       dir <= 1'b0;
                else if (!dir && (floor == 2'd0)) dir <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (floor == 2'd0)
            assert (pos == 4'b0001);
endmodule

module debounce_stability (
    input wire clk,
    input wire rst,
    input wire sample,
    input wire raw,
    output reg out
);
    reg [2:0] cnt;   // consecutive samples disagreeing with out
    reg [2:0] rem;   // samples still required before out may flip

    initial out = 1'b0;
    initial cnt = 3'd0;
    initial rem = 3'd4;

    always @(posedge clk) begin
        if (rst) begin
            out <= 1'b0;
            cnt <= 3'd0;
            rem <= 3'd4;
        end else if (sample) begin
            if (raw == out) begin
                cnt <= 3'd0;
                rem <= 3'd4;
            end else if (cnt == 3'd4) begin
                out <= raw;
                cnt <= 3'd0;
                rem <= 3'd4;
            end else begin
                cnt <= cnt + 3'd1;
                rem <= rem - 3'd1;
            end
        end
    end

    always @(posedge clk)
        if (cnt == 3'd4) assert (rem != 3'd4);
endmodule

module pwm_antiphase (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire load,
    input wire [3:0] i_duty,
    output wire pwm_a,
    output wire pwm_b
);
    // ramp counter and its anti-phase mirror (kept complementary by construction)
    reg [3:0] cnt  = 4'd0;
    reg [3:0] cntb = 4'd15;
    // duty for each channel, split so the pair always sums to full scale
    reg [3:0] duty_a = 4'd8;
    reg [3:0] duty_b = 4'd7;

    always @(posedge clk)
        if (rst) begin
            cnt  <= 4'd0;
            cntb <= 4'd15;
        end else if (ce) begin
            cnt  <= cnt  + 4'd1;
            cntb <= cntb - 4'd1;
        end

    always @(posedge clk)
        if (rst) begin
            duty_a <= 4'd8;
            duty_b <= 4'd7;
        end else if (load) begin
            duty_a <= i_duty;
            duty_b <= 4'd15 - i_duty;
        end

    assign pwm_a = (cnt  < duty_a);
    assign pwm_b = (cntb < duty_b);

    // the two half-bridge drives must never be asserted together
    always @(*)
        if (pwm_a) assert (!pwm_b);
endmodule

module prio_pipe (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] req,
    output reg b_valid,
    output reg [2:0] b_idx
);
    reg [7:0] a_vec;
    reg       a_valid;
    reg [7:0] b_vec;

    initial begin
        a_vec = 8'h00; a_valid = 1'b0;
        b_vec = 8'h00; b_idx = 3'd0; b_valid = 1'b0;
    end

    // combinational priority encode of the stage-1 vector (default index 0)
    wire [2:0] a_idx = a_vec[7] ? 3'd7 :
                       a_vec[6] ? 3'd6 :
                       a_vec[5] ? 3'd5 :
                       a_vec[4] ? 3'd4 :
                       a_vec[3] ? 3'd3 :
                       a_vec[2] ? 3'd2 :
                       a_vec[1] ? 3'd1 : 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            a_vec <= 8'h00; a_valid <= 1'b0;
            b_vec <= 8'h00; b_idx <= 3'd0; b_valid <= 1'b0;
        end else if (ce) begin
            a_vec   <= req;
            a_valid <= (req != 8'h00);
            b_vec   <= a_vec;
            b_idx   <= a_idx;
            b_valid <= a_valid;
        end
    end

    always @(posedge clk)
        if (b_valid)
            assert (b_vec[b_idx]);
endmodule

module isqrt_ladder (
    input wire clk,
    input wire rst,
    input wire step,
    output reg [2:0] k,
    output reg [5:0] sq,
    output reg [4:0] odd
);
    initial k   = 3'd0;
    initial sq  = 6'd0;
    initial odd = 5'd1;

    always @(posedge clk) begin
        if (rst) begin
            k   <= 3'd0;
            sq  <= 6'd0;
            odd <= 5'd1;
        end else if (step && k != 3'd7) begin
            k   <= k + 3'd1;
            sq  <= sq + {1'b0, odd};
            odd <= odd + 5'd2;
        end
    end

    // P: when the ladder index reaches 3, the accumulated square must be 9
    always @(posedge clk)
        if (k == 3'd3)
            assert (sq == 6'd9);
endmodule

module gray_cdc_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output reg  [2:0] bin,
    output reg  [2:0] gray,
    output reg  [2:0] prev_gray,
    output reg        past_ce
);
    initial bin       = 3'd0;
    initial gray      = 3'b000;
    initial prev_gray = 3'b000;
    initial past_ce   = 1'b0;

    wire [2:0] bin_nxt  = bin + 3'd1;
    wire [2:0] gray_nxt = bin_nxt ^ (bin_nxt >> 1);
    wire [2:0] delta    = gray ^ prev_gray;

    always @(posedge clk) begin
        if (rst) begin
            bin       <= 3'd0;
            gray      <= 3'b000;
            prev_gray <= 3'b000;
        end else if (ce) begin
            bin       <= bin_nxt;
            gray      <= gray_nxt;
            prev_gray <= gray;
        end
        past_ce <= ce && !rst;
    end

    // P: after an enabled step, the gray output changed in exactly one bit
    always @(posedge clk)
        if (past_ce)
            assert (delta == 3'b001 || delta == 3'b010 || delta == 3'b100);
endmodule

module vend_credit (
    input  wire clk,
    input  wire i_rst,
    input  wire i_nickel,
    input  wire i_dime,
    output wire o_dispense
);
    // credit counted in 5-cent units toward a 25c (5 unit) item
    reg [2:0] units;
    reg [4:0] credit_1h;   // one-hot shadow of the credit level
    initial units     = 3'd0;
    initial credit_1h = 5'b00001;

    wire       step   = i_nickel | i_dime;
    wire [2:0] amount = i_dime ? 3'd2 : 3'd1;
    wire [3:0] sum    = units + amount;

    assign o_dispense = step && (sum >= 4'd5);

    always @(posedge clk)
        if (i_rst) begin
            units     <= 3'd0;
            credit_1h <= 5'b00001;
        end else if (step) begin
            if (sum >= 4'd5) begin
                units     <= 3'd0;          // vend and clear credit
                credit_1h <= 5'b00001;
            end else begin
                units     <= sum[2:0];
                credit_1h <= i_dime ? (credit_1h << 2) : (credit_1h << 1);
            end
        end

    // P: outside reset the credit shadow is always exactly one-hot
    always @(*)
        if (!i_rst)
            assert ((credit_1h != 5'b00000) &&
                    ((credit_1h & (credit_1h - 5'b00001)) == 5'b00000));
endmodule

module crc8_check (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output reg  [7:0] crc,
    output reg        any_one
);
    // bit-serial CRC-8 reduction, polynomial 0x07
    initial begin
        crc     = 8'h00;
        any_one = 1'b0;
    end

    wire fb = crc[7] ^ din;

    always @(posedge clk) begin
        if (rst) begin
            crc     <= 8'h00;
            any_one <= 1'b0;
        end else if (ce) begin
            crc     <= {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);
            any_one <= any_one | din;
        end
    end

    // an all-zero stream can never push weight into the high nibble
    always @(posedge clk)
        if (any_one == 1'b0)
            assert (crc[7:4] == 4'h0);
endmodule

module chess_clock (
    input wire clk,
    input wire rst,
    input wire tick,
    input wire press,
    output reg run_w,
    output reg run_b,
    output reg active,
    output reg [2:0] t_w,
    output reg [2:0] t_b
);
    initial run_w  = 1'b1;
    initial run_b  = 1'b0;
    initial active = 1'b1;
    initial t_w    = 3'd5;
    initial t_b    = 3'd5;

    always @(posedge clk) begin
        if (rst) begin
            run_w <= 1'b1; run_b <= 1'b0; active <= 1'b1;
            t_w <= 3'd5;   t_b <= 3'd5;
        end else if (tick && active) begin
            if (press) begin
                run_w <= ~run_w;
                run_b <= ~run_b;
            end
            if (run_w && t_w != 3'd0) t_w <= t_w - 3'd1;
            if (run_b && t_b != 3'd0) t_b <= t_b - 3'd1;
            if ((run_w && t_w == 3'd1) || (run_b && t_b == 3'd1)) begin
                active <= 1'b0;
                run_w  <= 1'b0;
                run_b  <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (active) assert (!(run_w && run_b));
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output wire       o_done,
    output wire [4:0] o_src_off
);
    parameter [4:0] TOTAL = 5'd20;

    reg [4:0] remaining;
    reg [4:0] sent;
    initial remaining = TOTAL;
    initial sent      = 5'd0;

    always @(posedge clk)
        if (rst) begin
            remaining <= TOTAL;
            sent      <= 5'd0;
        end else if (i_ce && (remaining != 5'd0)) begin
            remaining <= remaining - 5'd1;
            sent      <= sent + 5'd1;
        end

    assign o_done    = (remaining == 5'd0);
    assign o_src_off = sent;

    always @(*)
        if (o_done)
            assert (sent == TOTAL);
endmodule

module lfsr_budget (
    input wire clk,
    input wire rst,
    input wire en,
    output reg [7:0] lfsr,
    output reg [2:0] draws,
    output reg [3:0] bits_used
);
    initial lfsr      = 8'h01;
    initial draws     = 3'd0;
    initial bits_used = 4'd0;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];

    always @(posedge clk) begin
        if (rst) begin
            lfsr      <= 8'h01;
            draws     <= 3'd0;
            bits_used <= 4'd0;
        end else if (en) begin
            if (draws != 3'd7) begin
                lfsr      <= {lfsr[6:0], fb};
                draws     <= draws + 3'd1;
                bits_used <= bits_used + 4'd2;
            end
        end
    end

    always @(posedge clk)
        if (draws != 3'd7)
            assert (bits_used <= 4'd12);
endmodule

module chess_clock (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire press,
    output wire o_frozen
);
    reg [3:0] tA;
    reg [3:0] tB;
    reg [4:0] sum;   // shadow of the combined remaining time
    reg       turn;
    initial tA  = 4'd15;
    initial tB  = 4'd15;
    initial sum = 5'd30;
    initial turn = 1'b0;

    wire frz = (tA == 4'd0) || (tB == 4'd0);
    assign o_frozen = frz;

    always @(posedge clk) begin
        if (rst) begin
            tA   <= 4'd15;
            tB   <= 4'd15;
            sum  <= 5'd30;
            turn <= 1'b0;
        end else if (ce) begin
            if (press)
                turn <= ~turn;
            else if (!frz) begin
                if (turn) tB <= tB - 4'd1;
                else      tA <= tA - 4'd1;
                sum <= sum - 5'd1;
            end
        end
    end

    always @(*)
        if (tA == 4'd0)
            assert (sum == {1'b0, tB});
endmodule

module rr_prio_encoder (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] req,
    output reg [2:0] ptr,
    output reg vld,
    output reg [2:0] gnt_idx
);
    reg [7:0] mask;
    initial begin ptr = 3'd0; mask = 8'h01; vld = 1'b0; gnt_idx = 3'd0; end

    // the rotating priority slot currently under consideration
    wire hit = |(req & mask);

    always @(posedge clk) begin
        if (rst) begin
            ptr     <= 3'd0;
            mask    <= 8'h01;
            vld     <= 1'b0;
            gnt_idx <= 3'd0;
        end else if (ce) begin
            ptr  <= ptr + 3'd1;
            mask <= {mask[6:0], mask[7]};
            vld  <= hit;
            if (hit) gnt_idx <= ptr;
        end
    end

    always @(posedge clk)
        if (ptr == 3'd0)
            assert (mask == 8'h01);
endmodule

module pwm_dimmer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] duty_in,
    output wire pwm_out
);
    reg [7:0] cnt      = 8'd0;   // free-running ramp
    reg [7:0] duty_reg = 8'd0;   // duty latched at period start
    reg [7:0] high_cnt = 8'd0;   // high-time accumulated this period

    always @(posedge clk)
        if (rst) begin
            cnt      <= 8'd0;
            duty_reg <= 8'd0;
            high_cnt <= 8'd0;
        end else if (ce) begin
            if (cnt == 8'd0) begin
                duty_reg <= duty_in;
                high_cnt <= (duty_in != 8'd0) ? 8'd1 : 8'd0;
                cnt      <= 8'd1;
            end else if (cnt == 8'hFF) begin
                cnt      <= 8'd0;
                high_cnt <= 8'd0;
            end else begin
                cnt      <= cnt + 8'd1;
                high_cnt <= high_cnt + ((cnt < duty_reg) ? 8'd1 : 8'd0);
            end
        end

    assign pwm_out = (cnt < duty_reg);

    always @(posedge clk)
        if (pwm_out)
            assert (high_cnt < duty_reg);
endmodule

module watchdog (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output reg fault
);
    reg [3:0] timer;
    reg [3:0] elapsed;
    initial begin timer = 4'd8; elapsed = 4'd0; fault = 1'b0; end

    always @(posedge clk) begin
        if (rst) begin
            timer   <= 4'd8;
            elapsed <= 4'd0;
            fault   <= 1'b0;
        end else if (i_ce) begin
            if (ack) begin
                timer   <= 4'd8;
                elapsed <= 4'd0;
                fault   <= 1'b0;
            end else if (kick && !fault) begin
                timer   <= 4'd8;
                elapsed <= 4'd0;
            end else begin
                if (timer != 4'd0)   timer   <= timer - 4'd1;
                if (elapsed != 4'd8) elapsed <= elapsed + 4'd1;
                if (timer == 4'd1)   fault   <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (elapsed == 4'd8)
            assert (fault);
endmodule

module alu_accum_slice (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       i_sub,
    output reg  [7:0] o_result,
    output wire       o_zero
);
    reg [6:0] half;

    initial o_result = 8'd0;
    initial half     = 7'd0;

    assign o_zero = (o_result == 8'd0);

    always @(posedge clk) begin
        if (rst) begin
            o_result <= 8'd0;
            half     <= 7'd0;
        end else if (i_ce) begin
            o_result <= i_sub ? (o_result - 8'd2) : (o_result + 8'd2);
            half     <= i_sub ? (half     - 7'd1) : (half     + 7'd1);
        end
    end

    // P: whenever the half-step tracker is at zero, the registered ALU result is zero
    always @(posedge clk)
        if (half == 7'd0)
            assert (o_result == 8'd0);
endmodule

module crc8_bitpos (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire din,
    output reg [7:0] crc,
    output wire byte_done
);
    reg [7:0] active;
    reg [2:0] bitcnt;
    reg [7:0] crc_last;

    initial begin
        crc      = 8'hFF;
        active   = 8'h01;
        bitcnt   = 3'd0;
        crc_last = 8'h00;
    end

    wire       fb      = crc[7] ^ din;
    wire [7:0] crc_nxt = {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);

    assign byte_done = ce && active[7];

    always @(posedge clk) begin
        if (rst) begin
            crc      <= 8'hFF;
            active   <= 8'h01;
            bitcnt   <= 3'd0;
            crc_last <= 8'h00;
        end else if (ce) begin
            crc    <= crc_nxt;
            active <= {active[6:0], active[7]};
            bitcnt <= bitcnt + 3'd1;
            if (active[7]) crc_last <= crc_nxt;
        end
    end

    always @(posedge clk)
        if (bitcnt == 3'd7)
            assert (active == 8'h80);
endmodule

module sqacc (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output wire [5:0] o_sq,
    output wire [2:0] o_cnt
);
    // accumulates successive odd numbers, so sq tracks cnt*cnt (mod 64)
    reg [2:0] cnt;
    reg [5:0] sq;
    reg [3:0] odd;

    initial cnt = 3'd0;
    initial sq  = 6'd0;
    initial odd = 4'd1;

    always @(posedge clk)
        if (rst) begin
            cnt <= 3'd0;
            sq  <= 6'd0;
            odd <= 4'd1;
        end else if (step) begin
            cnt <= cnt + 3'd1;
            sq  <= sq + {2'b00, odd};
            odd <= odd + 4'd2;
        end

    assign o_sq  = sq;
    assign o_cnt = cnt;

    // P: at the third index the accumulated value must be the perfect square 9
    always @(*)
        if (cnt == 3'd3)
            assert (sq == 6'd9);
endmodule

module rotstage (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire i_valid,
    input wire [3:0] i_amt,
    input wire [15:0] i_data,
    output wire o_valid,
    output wire [15:0] o_data
);
    reg v0, v1, v2, v3;
    reg [2:0] pend;
    reg [15:0] d0, d1, d2, d3;
    reg [3:0] a0, a1, a2;

    initial begin
        v0 = 0; v1 = 0; v2 = 0; v3 = 0; pend = 0;
        d0 = 0; d1 = 0; d2 = 0; d3 = 0;
        a0 = 0; a1 = 0; a2 = 0;
    end

    always @(posedge clk) begin
        if (rst) begin
            v0 <= 0; v1 <= 0; v2 <= 0; v3 <= 0; pend <= 0;
        end else if (ce) begin
            v0 <= i_valid;
            v1 <= v0;
            v2 <= v1;
            v3 <= v2;
            pend <= pend + (i_valid ? 3'd1 : 3'd0) - (v3 ? 3'd1 : 3'd0);
            d0 <= i_amt[0] ? {i_data[14:0], i_data[15]} : i_data;
            a0 <= i_amt;
            d1 <= a0[1] ? {d0[13:0], d0[15:14]} : d0;
            a1 <= a0;
            d2 <= a1[2] ? {d1[11:0], d1[15:12]} : d1;
            a2 <= a1;
            d3 <= a2[3] ? {d2[7:0], d2[15:8]} : d2;
        end
    end

    assign o_valid = v3;
    assign o_data  = d3;

    always @(posedge clk)
        if (pend == 3'd0) assert (!v3);
endmodule

module sorted_pair (
    input wire clk,
    input wire rst,
    input wire ins,
    input wire pop,
    input wire [3:0] val,
    output reg [4:0] sum
);
    reg [3:0] k0, k1;
    reg [1:0] count;
    initial begin k0 = 0; k1 = 0; count = 0; sum = 0; end

    wire do_ins = ins && !pop && (count != 2'd2);
    wire do_pop = pop && !ins && (count != 2'd0);

    always @(posedge clk) begin
        if (rst) begin
            k0 <= 4'd0; k1 <= 4'd0; count <= 2'd0; sum <= 5'd0;
        end else if (do_ins) begin
            if (count == 2'd0) begin
                k0 <= val;
            end else if (val < k0) begin
                k0 <= val; k1 <= k0;
            end else begin
                k1 <= val;
            end
            count <= count + 2'd1;
            sum   <= sum + {1'b0, val};
        end else if (do_pop) begin
            k0    <= k1;
            k1    <= 4'd0;
            count <= count - 2'd1;
            sum   <= sum - {1'b0, k0};
        end
    end

    always @(posedge clk)
        if (count == 2'd0)
            assert (sum == 5'd0);
endmodule

module token_bucket (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire req,
    input  wire drip,
    output wire grant
);
    reg [3:0] tokens = 4'd8;   // tokens currently in the bucket
    reg [3:0] free   = 4'd0;   // room left in the bucket (shadow accounting)

    wire spend   = ce && req  && (tokens != 4'd0);
    wire refill  = ce && drip && (free   != 4'd0);

    assign grant = spend;

    always @(posedge clk) begin
        if (rst) begin
            tokens <= 4'd8;
            free   <= 4'd0;
        end else begin
            tokens <= tokens - spend + refill;
            free   <= free   + spend - refill;
        end
    end

    // P: if the bucket is not completely full, at least one slot's worth of
    // tokens is missing, so occupancy cannot exceed CAP-1.
    always @(posedge clk)
        if (free != 4'd0)
            assert (tokens <= 4'd7);
endmodule

module stack_hwm (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] top
);
    reg [3:0] sp;
    reg [3:0] hwm;
    reg [7:0] mem [0:15];
    initial begin sp = 4'd0; hwm = 4'd0; end

    wire do_push = ce && push && (sp != 4'd8);
    wire do_pop  = ce && pop  && (sp != 4'd0);
    wire [3:0] nxt = sp + 4'd1;

    assign top = (sp == 4'd0) ? 8'h00 : mem[sp - 4'd1];

    always @(posedge clk) begin
        if (rst) begin
            sp  <= 4'd0;
            hwm <= 4'd0;
        end else begin
            case ({do_push, do_pop})
                2'b10: begin
                    mem[sp] <= din;
                    sp <= nxt;
                    if (nxt > hwm) hwm <= nxt;
                end
                2'b01: sp <= sp - 4'd1;
                default: ;
            endcase
        end
    end

    always @(posedge clk)
        if (sp == 4'd8)
            assert (hwm == 4'd8);
endmodule

module vend_credit (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_dime,
    output wire o_dispense,
    output wire [5:0] o_change
);
    reg [3:0] units = 0;      // credit in 5-cent units
    reg [5:0] cents = 0;      // credit in cents
    reg       dispense = 0;
    reg [5:0] change = 0;

    wire [3:0] inc_u = i_dime ? 4'd2  : 4'd1;
    wire [5:0] inc_c = i_dime ? 6'd10 : 6'd5;
    wire [3:0] nu = units + inc_u;
    wire [5:0] nc = cents + inc_c;

    always @(posedge clk)
        if (i_reset) begin
            units    <= 4'd0;
            cents    <= 6'd0;
            dispense <= 1'b0;
            change   <= 6'd0;
        end else if (i_ce) begin
            if (nu >= 4'd5) begin
                units    <= nu - 4'd5;
                cents    <= nc - 6'd25;
                change   <= nc - 6'd25;
                dispense <= 1'b1;
            end else begin
                units    <= nu;
                cents    <= nc;
                dispense <= 1'b0;
            end
        end

    assign o_dispense = dispense;
    assign o_change   = change;

    always @(posedge clk)
        if (dispense) assert (change <= 6'd5);
endmodule

module substr_search (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] in_char,
    output reg [1:0] idx,
    output reg found
);
    localparam [7:0] TGT = 8'h61; // 'a'

    initial idx   = 2'd0;
    initial found = 1'b0;

    // matches the 3-character run "aaa"; freezes once idx saturates at 3
    always @(posedge clk) begin
        if (rst) begin
            idx   <= 2'd0;
            found <= 1'b0;
        end else if (ce && idx != 2'd3) begin
            if (in_char == TGT) begin
                idx <= idx + 2'd1;
                if (idx == 2'd2)
                    found <= 1'b1;
            end else begin
                idx <= 2'd0;
            end
        end
    end

    // P: the found flag implies a non-empty partial match is held
    always @(posedge clk)
        if (found) assert (idx != 2'd0);
endmodule

module rr_arbiter_pri (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire [3:0] req,
    output wire [3:0] gnt,
    output reg  [3:0] pri,
    output reg  [1:0] idx
);
    initial pri = 4'b0001;
    initial idx = 2'd0;

    // only the requester currently pointed at by the rotating priority wins
    assign gnt = req & pri;

    wire low_pri = pri[0] | pri[1];   // priority pointer sits in lower half
    wire idx_hi  = idx[1];            // binary index says upper half

    always @(posedge clk) begin
        if (rst) begin
            pri <= 4'b0001;
            idx <= 2'd0;
        end else if (step) begin
            pri <= {pri[2:0], pri[3]};
            idx <= idx + 2'd1;
        end
    end

    always @(posedge clk)
        if (|gnt)
            assert (!(low_pri && idx_hi));
endmodule

module alu_budget (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [7:0] i_step,
    output wire [7:0] o_acc,
    output wire o_zero,
    output wire o_full
);
    localparam [7:0] LIMIT = 8'd200;

    reg [7:0] acc;   // accumulated result
    reg [7:0] rem;   // headroom credited to the accumulator
    initial acc = 8'd0;
    initial rem = LIMIT;

    wire grant = i_ce && (rem >= i_step);

    always @(posedge clk)
        if (rst) begin
            acc <= 8'd0;
            rem <= LIMIT;
        end else if (grant) begin
            acc <= acc + i_step;
            rem <= rem - i_step;
        end

    assign o_acc  = acc;
    assign o_zero = (acc == 8'd0);
    assign o_full = (rem == 8'd0);

    // P: a nonzero accumulation never exceeds its saturation bound
    always @(*)
        if (!o_zero) assert (acc <= LIMIT);
endmodule
